let noCriticalInjuries = data?.roll?.metadata?.noCriticalInjuries || false;

let roll = {
  ...data.roll,
  dice: [...(data?.roll?.dice || [])],
  total: data?.roll?.total !== undefined ? data?.roll?.total : 0,
};

